def transform_grid(grid):
    """Transform an input grid according to the pattern"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    output = [[0 for _ in range(cols)] for _ in range(rows)]

    # Find special row (last row with non-0, non-1 values)
    special_row = -1
    for r in range(rows - 1, -1, -1):
        for c in range(cols):
            if grid[r][c] != 0 and grid[r][c] != 1:
                special_row = r
                break
        if special_row != -1:
            break

    if special_row == -1:
        return output

    # Initialize output as copy of input
    for r in range(rows):
        for c in range(cols):
            output[r][c] = grid[r][c]

    # For each column in special row, apply pattern if value >= 2
    for c in range(cols):
        v = grid[special_row][c]
        if v < 2:
            continue

        # Determine span
        if v <= 4:
            span = 5
        elif v <= 7:
            span = 4
        else:
            span = 3

        start_row = special_row - span + 1

        # Fill column: special value at top, 1s below, original at special row
        for r in range(start_row, special_row + 1):
            if start_row == start_row:  # First row
                output[r][c] = v
            elif r == special_row:  # Last row
                output[r][c] = v
            else:
                output[r][c] = 1

    return output

